INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Референдум Российской Федерации','Представитель инициаторов предлагает голосование по федеральному референдуму с возможностью проследить бюллетень каждого гражданина. Какое правило нарушено?','["Достаточно согласия наблюдателя на отслеживание бюллетеней","Тайное голосование исключает контроль за волеизъявлением гражданина","Контроль допустим по решению территориальной комиссии","Тайна обязательна лишь на региональном референдуме"]'::jsonb,1,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 2','https://www.consultant.ru/document/cons_doc_LAW_48221/371262287bac4a9a67fec5011add3e6093957fae/','Статья 2 требует тайного голосования, исключающего контроль за волеизъявлением.',true),
('Референдум Российской Федерации','Муниципальная администрация требует от работников обязательного участия в федеральном референдуме. Какая правовая оценка верна?','["Участие свободное и добровольное; принуждение недопустимо","Работодатель вправе требовать явки без контроля выбора","Обязательность явки устанавливает муниципальная администрация","Принуждение допустимо при объявленной кампании информирования"]'::jsonb,0,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 2','https://www.consultant.ru/document/cons_doc_LAW_48221/371262287bac4a9a67fec5011add3e6093957fae/','Статья 2 запрещает принуждение к участию или неучастию.',true),
('Референдум Российской Федерации','Комиссия хочет предоставить руководителям предприятий по два голоса, другим гражданам по одному. Какой принцип применим?','["Дополнительный голос допускается при налоговом резидентстве","Равенство относится только к выборам депутатов","Количество голосов вправе определять региональная комиссия","Все участники голосуют на равных основаниях и имеют равное число голосов"]'::jsonb,3,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 2','https://www.consultant.ru/document/cons_doc_LAW_48221/371262287bac4a9a67fec5011add3e6093957fae/','Статья 2 устанавливает равное число голосов у участников.',true),
('Референдум Российской Федерации','Гражданину РФ исполнилось восемнадцать лет ко дню федерального референдума. Иные ограничения отсутствуют. Может ли он голосовать?','["Нет, необходим возраст 21 год","Да, только после двух лет участия в выборах","Да, активное право возникает по достижении 18 лет","Нет, если он не состоял в инициативной группе"]'::jsonb,2,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_48221/324516922432d50bb591c08bd13dbfc0ce6686e6/','Статья 5 предусматривает право гражданина РФ голосовать с 18 лет.',true),
('Референдум Российской Федерации','Гражданин РФ постоянно живёт за пределами России. Теряет ли он вследствие этого право голосовать на федеральном референдуме?','["Да, голосовать вправе только проживающие в РФ","Нет, проживающий за рубежом гражданин сохраняет право участия","Нет, но голос за рубежом учитывается как половина голоса","Право сохраняется только у сотрудников дипломатических представительств"]'::jsonb,1,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_48221/324516922432d50bb591c08bd13dbfc0ce6686e6/','Статья 5 гарантирует право участия российским гражданам за рубежом.',true),
('Референдум Российской Федерации','Гражданин, признанный судом недееспособным, хочет проголосовать на федеральном референдуме. Какой вариант соответствует закону?','["Он не имеет права участвовать в референдуме","Он голосует с письменного согласия опекуна","Он участвует на равных, если достиг 25 лет","Решение принимает участковая комиссия по своему усмотрению"]'::jsonb,0,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_48221/324516922432d50bb591c08bd13dbfc0ce6686e6/','Статья 5 исключает участие лиц, признанных судом недееспособными.',true),
('Референдум Российской Федерации','На федеральный референдум предложили вынести изменение конституционного статуса одного из субъектов РФ. Какова оценка вопроса?','["Допускается при решении законодательного органа субъекта","Допускается при голосовании только жителей субъекта","Возможен, если срок голосования назначит Совет Федерации","Такой вопрос не может выноситься на референдум"]'::jsonb,3,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_48221/1bc4cc511304799d3613c0477ff931fb2850d9b8/','Статья 6 исключает вопросы изменения закреплённого Конституцией статуса субъектов.',true),
('Референдум Российской Федерации','Инициаторы предлагают федеральный референдум о досрочном прекращении полномочий Президента РФ. Может ли вопрос быть вынесен?','["Да, если собрано два миллиона подписей","Да, если Совет Федерации одобрит инициативу","Нет, такой предмет прямо исключён ФКЗ","Да, если голосование назначено за сто дней"]'::jsonb,2,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_48221/1bc4cc511304799d3613c0477ff931fb2850d9b8/','Статья 6 запрещает вопросы досрочного прекращения или продления президентских полномочий.',true),
('Референдум Российской Федерации','На федеральный референдум предлагается вынести персональный состав федерального органа власти. Что следует из закона?','["Допускается, если орган был учреждён федеральным законом","Персональный состав федеральных органов не может быть предметом референдума","Допускается, если проект составлен в форме бюллетеня","Допускается при голосовании не менее двух третей граждан"]'::jsonb,1,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_48221/1bc4cc511304799d3613c0477ff931fb2850d9b8/','Статья 6 исключает персональный состав федеральных органов из предметов голосования.',true),
('Референдум Российской Федерации','Авторы вынесли вопрос, допускающий две несовместимые трактовки последствий. Какой правовой критерий нарушен?','["Вопрос должен допускать однозначный ответ и определённые правовые последствия","Необходимо лишь не превышать десять слов в формулировке","Содержательная неоднозначность устраняется подсчётом явки","Любая формулировка допустима при наличии пояснительной записки"]'::jsonb,0,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_48221/1bc4cc511304799d3613c0477ff931fb2850d9b8/','Статья 6 требует единственного понимания вопроса и ясности последствий.',true),
('Референдум Российской Федерации','Разные инициативные группы предложили альтернативные вопросы федерального референдума. Исключает ли закон такую возможность в принципе?','["Да, допустим только один вопрос для всех групп","Да, пока одна группа не откажется от инициативы","Да, референдум всегда может содержать лишь один вопрос","Нет, закон допускает альтернативные вопросы разных групп"]'::jsonb,3,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_48221/1bc4cc511304799d3613c0477ff931fb2850d9b8/','Статья 6 допускает предложение альтернативных вопросов разными инициативными группами.',true),
('Референдум Российской Федерации','В стране действует чрезвычайное положение на всей территории. Можно ли начать новую гражданскую инициативу федерального референдума?','["Да, достаточно последующего судебного подтверждения","Да, если имеются подписи из большинства субъектов","Нет, инициирование и назначение референдума в этих условиях исключены","Да, при поддержке двух третей членов инициативной группы"]'::jsonb,2,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_48221/b41d201f7638247d47e38c50ad6a27c10d667d18/','Статья 7 исключает выдвижение инициативы в период общероссийского ЧП или ВП.',true),
('Референдум Российской Федерации','Чрезвычайное положение на всей территории РФ отменено месяц назад. Когда по общему правилу может быть назначен федеральный референдум?','["Немедленно в день отмены режима","По истечении трёх месяцев со дня отмены особого режима","После истечения шестидесяти суток со дня введения режима","Только после следующего созыва Государственной Думы"]'::jsonb,1,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_48221/b41d201f7638247d47e38c50ad6a27c10d667d18/','Статья 7 предусматривает трёхмесячный период после отмены режима.',true),
('Референдум Российской Федерации','Инициативная группа пытается повторить референдум с вопросом того же содержания через год после обнародования результатов. Какая норма препятствует проведению?','["Повторный референдум по тому же вопросу запрещён в течение двух лет","Повтор разрешается через один год при прежней формулировке","Запрет действует только в пределах одного квартала","Повторное голосование допустимо сразу при ином инициаторе"]'::jsonb,0,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_48221/b41d201f7638247d47e38c50ad6a27c10d667d18/','Статья 7 устанавливает двухлетний запрет повторения вопроса.',true),
('Референдум Российской Федерации','Назначен федеральный референдум по гражданской инициативе на период общероссийской федеральной избирательной кампании. Как оценить такую дату?','["Достаточно сменить инициатора на региональную комиссию","Запрет касается только муниципальных референдумов","Любая кампания разрешает одновременный референдум без ограничений","Проведение референдума в такой период запрещено с предусмотренными законом исключениями"]'::jsonb,3,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_48221/b41d201f7638247d47e38c50ad6a27c10d667d18/','Статья 7 запрещает проведение в период такой кампании, учитывая исключения статьи 6.',true),
('Референдум Российской Федерации','Для гражданской инициативы референдума собрано 1,9 млн подписей имеющих право участия граждан. Достаточно ли этого для установленного законом минимума?','["Да, достаточно полутора миллионов","Да, достаточно любого числа при поддержке ЦИК","Нет, необходимо не менее двух миллионов граждан","Да, если подписи представляют все субъекты РФ"]'::jsonb,2,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_48221/55e469d84acd7e91ca2c991f564180fc251ba01a/','Статья 14 предусматривает минимум два миллиона граждан.',true),
('Референдум Российской Федерации','Группа собрала два миллиона подписей, однако 75 тысяч подписантов проживают в одном субъекте РФ. Какое требование нарушено?','["Не допускается свыше 100 тысяч в одном субъекте","В одном субъекте не должно приходиться более 50 тысяч граждан-инициаторов","В одном субъекте должно быть не менее 75 тысяч подписантов","Ограничение действует только для граждан за пределами России"]'::jsonb,1,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_48221/55e469d84acd7e91ca2c991f564180fc251ba01a/','Статья 14 устанавливает предел 50 тысяч в одном субъекте.',true),
('Референдум Российской Федерации','Конституционное Собрание решает поставить на всенародное голосование проект новой Конституции. Допускает ли ФКЗ такую инициативу?','["Да, в случае, предусмотренном частью 3 статьи 135 Конституции","Нет, инициативу имеют лишь граждане с двумя миллионами подписей","Нет, проект Конституции выносится только Правительством","Да, при решении только Государственной Думы"]'::jsonb,0,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_48221/55e469d84acd7e91ca2c991f564180fc251ba01a/','Статья 14 отдельно закрепляет инициативу Конституционного Собрания.',true),
('Референдум Российской Федерации','Инициативная группа сформировала региональные подгруппы лишь в трети субъектов РФ. Что необходимо для соблюдения требований ФКЗ?','["Достаточно подгрупп в четверти субъектов","Необходимы подгруппы исключительно в федеральных округах","Подгруппы не обязательны, если все участники москвичи","Региональные подгруппы должны быть более чем в половине субъектов РФ"]'::jsonb,3,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48221/cf9eb4d2910bc0fe0cac8c806068cc5d07022897/','Статья 15 требует подгруппы более чем в половине субъектов РФ.',true),
('Референдум Российской Федерации','Региональная подгруппа гражданской инициативы референдума состоит из 90 проживающих в субъекте участников. Каков законный минимум?','["Не менее пятидесяти участников референдума","Не менее семидесяти пяти участников","Не менее ста участников референдума","Не менее двухсот участников"]'::jsonb,2,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48221/cf9eb4d2910bc0fe0cac8c806068cc5d07022897/','Статья 15 устанавливает минимум 100 участников в региональной подгруппе.',true),
('Референдум Российской Федерации','Президент получил документы гражданской инициативы федерального референдума. В какой срок он направляет вопрос в Конституционный Суд?','["Не позднее пяти дней после регистрации вопроса","Не позднее десяти дней после получения документов","Не позднее четырнадцати дней после завершения агитации","Не позднее месяца после решения Центральной избирательной комиссии"]'::jsonb,1,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 23','https://www.consultant.ru/document/cons_doc_LAW_48221/6a034c9b7a80bc07fdc4728ba1ee14e77031c213/','Статья 23 устанавливает десятидневный срок направления в КС РФ.',true),
('Референдум Российской Федерации','Конституционный Суд подтвердил конституционность инициативы референдума. В какой срок Президент назначает голосование?','["Не позднее пятнадцати дней после поступления решения Суда","Не позднее десяти дней после окончания сбора подписей","Не позднее тридцати дней после заседания Совета Федерации","Не позднее двух месяцев после первой региональной подгруппы"]'::jsonb,0,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 23','https://www.consultant.ru/document/cons_doc_LAW_48221/6a034c9b7a80bc07fdc4728ba1ee14e77031c213/','Статья 23 устанавливает пятнадцатидневный срок.',true),
('Референдум Российской Федерации','Президент назначает федеральный референдум на субботу через 80 дней после опубликования решения. Какой элемент срока нарушен?','["Голосование разрешается исключительно по вторникам","Необходим срок не менее ста двадцати дней","Дату определяет только Государственная Дума","Голосование назначается только на воскресенье с учётом предусмотренных исключений"]'::jsonb,3,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 23','https://www.consultant.ru/document/cons_doc_LAW_48221/6a034c9b7a80bc07fdc4728ba1ee14e77031c213/','Статья 23 допускает только воскресенье в интервале 60–100 дней.',true),
('Референдум Российской Федерации','После официального опубликования решения о назначении референдума предлагается назначить голосование через 45 дней. Правомерен ли срок?','["Да, закон устанавливает от 40 до 80 дней","Да, при участии более половины субъектов","Нет, общий интервал составляет от 60 до 100 дней","Нет, общий интервал составляет от 90 до 150 дней"]'::jsonb,2,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 23','https://www.consultant.ru/document/cons_doc_LAW_48221/6a034c9b7a80bc07fdc4728ba1ee14e77031c213/','Статья 23 устанавливает общий интервал 60–100 дней со дня публикации.',true),
('Референдум Российской Федерации','В голосовании участвовали ровно 50% граждан, включённых в списки. Признаётся ли федеральный референдум состоявшимся?','["Да, достаточно не менее половины","Нет, необходимо участие более половины включённых в списки граждан","Да, если большинство проголосовало «за»","Нет, необходимо участие двух третей граждан"]'::jsonb,1,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 80','https://www.consultant.ru/document/cons_doc_LAW_48221/27d0f586bb2863b0881688533a12d9fc868e5b32/','Статья 80 требует участия более половины внесённых в списки.',true),
('Референдум Российской Федерации','В состоявшемся референдуме за вопрос высказалось ровно 50% участвовавших. Принято ли решение по общему правилу?','["Нет, требуется более половины участвовавших в голосовании","Да, достаточно ровно половины голосов","Да, при отсутствии недействительных бюллетеней","Нет, необходимо две трети от всех зарегистрированных"]'::jsonb,0,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 80','https://www.consultant.ru/document/cons_doc_LAW_48221/27d0f586bb2863b0881688533a12d9fc868e5b32/','Статья 80 требует большинства строго свыше половины проголосовавших.',true),
('Референдум Российской Федерации','Кто определяет результаты федерального референдума на основании протоколов комиссий субъектов и иных предусмотренных протоколов?','["Совет Федерации Российской Федерации","Правительство Российской Федерации","Конституционный Суд Российской Федерации","Центральная избирательная комиссия Российской Федерации"]'::jsonb,3,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 80','https://www.consultant.ru/document/cons_doc_LAW_48221/27d0f586bb2863b0881688533a12d9fc868e5b32/','Статья 80 поручает определение результатов ЦИК РФ.',true),
('Референдум Российской Федерации','Какой общий срок имеет ЦИК России на определение результатов федерального референдума после дня голосования?','["Не позднее двух недель после объявления итогов","Не позднее тридцати дней после голосования","Не позднее десяти дней после голосования","Не позднее трёх месяцев после голосования"]'::jsonb,2,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 80','https://www.consultant.ru/document/cons_doc_LAW_48221/27d0f586bb2863b0881688533a12d9fc868e5b32/','Статья 80 устанавливает срок в десять дней.',true),
('Референдум Российской Федерации','Принятое на федеральном референдуме решение ожидает отдельного утверждения Федеральным Собранием. Нужно ли оно?','["Да, его обязательно утверждает Государственная Дума","Нет, решение общеобязательно и не нуждается в дополнительном утверждении","Да, требуется согласование Правительства","Да, оно действует лишь после подтверждения Советом Федерации"]'::jsonb,1,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 83','https://www.consultant.ru/document/cons_doc_LAW_48221/c989c27ca53da099b9f423e0e6f24e8b03fde9a5/','Статья 83 исключает дополнительное утверждение решения.',true),
('Референдум Российской Федерации','С какого момента по общему правилу вступает в силу решение, принятое на федеральном референдуме?','["Со дня официального опубликования ЦИК результатов референдума","С момента завершения подсчёта на первом участке","Через семь дней после утверждения Советом Федерации","По истечении шести месяцев со дня голосования"]'::jsonb,0,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 83','https://www.consultant.ru/document/cons_doc_LAW_48221/c989c27ca53da099b9f423e0e6f24e8b03fde9a5/','Статья 83 связывает вступление в силу с официальной публикацией результатов.',true),
('Референдум Российской Федерации','Орган власти хочет отменить решение федерального референдума обычным актом, хотя в самом решении иной порядок не указан. Допустимо ли это?','["Да, любой более поздний акт отменяет референдум","Да, достаточно распоряжения Правительства","Да, при согласии двух региональных парламентов","Нет, изменение или отмена осуществляется решением на новом референдуме"]'::jsonb,3,'ФКЗ от 28.06.2004 № 5-ФКЗ «О референдуме Российской Федерации»','статья 83','https://www.consultant.ru/document/cons_doc_LAW_48221/c989c27ca53da099b9f423e0e6f24e8b03fde9a5/','Статья 83 предусматривает новый референдум, если само решение не содержит иного порядка.',true),
('Чрезвычайное положение: правовой режим','На территории субъекта требуется ввести чрезвычайное положение. Какой акт непосредственно вводит такой режим?','["Законодательный акт субъекта РФ с последующим одобрением Правительства","Постановление губернатора с последующим уведомлением Думы","Указ Президента Российской Федерации с незамедлительным уведомлением обеих палат","Распоряжение Председателя Правительства по поручению губернатора"]'::jsonb,2,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_31866/b0e563d0173020cfacdfda6c47c944100b5c78ef/','Статья 4 относит введение ЧП к указу Президента.',true),
('Чрезвычайное положение: правовой режим','Президент ввёл чрезвычайное положение и направил указ лишь в Государственную Думу на утверждение. Какую обязательную процедуру пропустили?','["Утверждение Центральной избирательной комиссией","Незамедлительную передачу указа на утверждение Совету Федерации","Подписание указа руководителем регионального парламента","Предварительную регистрацию указа в Конституционном Суде"]'::jsonb,1,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_31866/b0e563d0173020cfacdfda6c47c944100b5c78ef/','Статья 4 требует направления указа Совету Федерации.',true),
('Чрезвычайное положение: правовой режим','В проекте указа о чрезвычайном положении описаны причины и границы территории, но не установлены временные ограничения прав. Что нарушено?','["Требование указать исчерпывающий перечень временных ограничений","Требование указать результат парламентских выборов","Требование приложить текст региональной стратегии","Требование установить выборы нового губернатора"]'::jsonb,0,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_31866/09eb435cc28b3d403746b6da0856a8d4d4d0b607/','Статья 5 требует исчерпывающего перечня ограничений прав.',true),
('Чрезвычайное положение: правовой режим','В указе о ЧП указана территория, но не обозначены срок действия и момент вступления в силу. Какое исправление обязательно?','["Указать срок лишь после отмены ЧП","Заменить срок названием должностного лица","Определить сроки только на заседании регионального парламента","Внести время вступления в силу и срок действия режима"]'::jsonb,3,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_31866/09eb435cc28b3d403746b6da0856a8d4d4d0b607/','Статья 5 требует указания начала и срока режима.',true),
('Чрезвычайное положение: правовой режим','В проекте указа о введении чрезвычайного положения не названы ответственные исполнители мер. Соответствует ли это ФКЗ?','["Да, исполнители определяются исключительно по окончании режима","Да, это всегда полномочие только муниципалитета","Нет, необходимо определить ответственные государственные органы или должностных лиц","Да, если указ опубликован в федеральных СМИ"]'::jsonb,2,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_31866/09eb435cc28b3d403746b6da0856a8d4d4d0b607/','Статья 5 требует определения органов или лиц, ответственных за меры.',true),
('Чрезвычайное положение: правовой режим','Совет Федерации получил информацию о введённом чрезвычайном положении и собирается обсуждать вопрос спустя пять суток после обнародования указа. Каков законный предельный срок?','["Не более 24 часов с обнародования указа","Не более 72 часов с обнародования указа","Не более 10 дней после завершения режима","Не более 7 суток после поступления запроса Правительства"]'::jsonb,1,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_31866/ab142d8c32c0afd1b0db44633d0cce442fa41254/','Статья 7 требует рассмотрения указа в 72-часовой срок.',true),
('Чрезвычайное положение: правовой режим','Совет Федерации не утвердил президентский указ о ЧП. Что происходит по истечении 72 часов с момента его обнародования?','["Указ утрачивает силу, население извещается соответствующим образом","Указ продолжает действовать ещё 30 суток","Вопрос автоматически передаётся на голосование Государственной Думы","Указ приобретает силу федерального закона"]'::jsonb,0,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_31866/ab142d8c32c0afd1b0db44633d0cce442fa41254/','Статья 7 устанавливает прекращение действия неутверждённого указа.',true),
('Чрезвычайное положение: правовой режим','Чрезвычайное положение введено во время парламентских каникул. Обязан ли сенатор ждать специального вызова для рассмотрения указа?','["Да, специальный вызов является обязательным условием участия","Да, сенатор вправе прибыть после завершения режима","Нет, решение по указу принимает только Президиум Правительства","Нет, должен прибыть к месту заседания в возможно короткий срок без специального вызова"]'::jsonb,3,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_31866/ab142d8c32c0afd1b0db44633d0cce442fa41254/','Статья 7 требует прибытия сенаторов без специального вызова.',true),
('Чрезвычайное положение: правовой режим','Президент ввёл чрезвычайное положение на всей территории России сроком на 45 суток одним указом. Какой максимум предусмотрен для такого случая?','["45 суток; указанная продолжительность является максимумом","60 суток; никаких ограничений меньше 60 нет","30 суток; более длительный первоначальный срок не допускается","90 суток по решению Совета Федерации"]'::jsonb,2,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_31866/d98e52c36ef8dc4a291272e2fa5050bbfd203c25/','Статья 9 ограничивает первоначальный срок общероссийского ЧП 30 сутками.',true),
('Чрезвычайное положение: правовой режим','Для отдельной территории введено чрезвычайное положение. Каков максимальный первоначальный срок?','["30 суток независимо от масштаба территории","60 суток","45 суток независимо от оснований","90 суток при отсутствии выборов"]'::jsonb,1,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_31866/d98e52c36ef8dc4a291272e2fa5050bbfd203c25/','Статья 9 допускает срок до 60 суток для отдельных местностей.',true),
('Чрезвычайное положение: правовой режим','Цели ЧП за первоначальный срок не достигнуты. Какой законный способ продления предусмотрен?','["Новый указ Президента с соблюдением правил введения чрезвычайного положения","Автоматическое бессрочное продление по решению региональной администрации","Распоряжение муниципальной комиссии без участия Президента","Продление телефонным уведомлением Совета Федерации"]'::jsonb,0,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_31866/d98e52c36ef8dc4a291272e2fa5050bbfd203c25/','Статья 9 допускает продление указом Президента по процедуре введения режима.',true),
('Чрезвычайное положение: правовой режим','Вводится ЧП, и необходим временный особый порядок продажи продуктов первой необходимости. Допускает ли ФКЗ такую меру?','["Нет, продовольственное регулирование исключено","Да, но только после отдельного федерального референдума","Нет, меры статьи 11 касаются исключительно транспорта","Да, это одна из возможных мер статьи 11"]'::jsonb,3,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_31866/eb55f4ea1bde28872248377425ff1ca9b3db8150/','Статья 11 предусматривает особый порядок продажи и распределения.',true),
('Чрезвычайное положение: правовой режим','В период ЧП предлагается приостановить работу опасного производства с радиоактивными веществами. Допустима ли мера?','["Нет, остановка опасных производств запрещена","Да, только по договору с предприятием","Да, при соблюдении режима и перечня мер указа","Нет, указ может регулировать исключительно митинги"]'::jsonb,2,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_31866/eb55f4ea1bde28872248377425ff1ca9b3db8150/','Статья 11 допускает приостановление опасных производств.',true),
('Чрезвычайное положение: правовой режим','Власти хотят эвакуировать культурные ценности в безопасные районы при реальной угрозе уничтожения из-за ЧП. Какая правовая основа применима?','["Эвакуация ценностей допускается только на военном положении","Это допустимая мера статьи 11 при реальной угрозе ценностям","Закон требует их обязательной приватизации","Эвакуация ценностей исключена из возможных мер ЧП"]'::jsonb,1,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_31866/eb55f4ea1bde28872248377425ff1ca9b3db8150/','Статья 11 допускает эвакуацию материальных и культурных ценностей.',true),
('Чрезвычайное положение: правовой режим','Чрезвычайное положение введено вследствие вооружённого мятежа. Может ли президентский указ предусмотреть комендантский час дополнительно к мерам статьи 11?','["Да, при обстоятельствах пункта «а» статьи 3 это предусмотрено статьёй 12","Нет, комендантский час применим лишь при эпидемиях","Да, но его может вводить исключительно муниципальный совет","Нет, комендантский час предусмотрен только ФКЗ о военном положении"]'::jsonb,0,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 12','https://www.consultant.ru/document/cons_doc_LAW_31866/75a9b175e0a4d0c3074be68f272c7ac670e7eafc/','Статья 12 предусматривает комендантский час при обстоятельствах пункта «а» статьи 3.',true),
('Чрезвычайное положение: правовой режим','В условиях ЧП из-за массовых беспорядков планируется временно ограничить деятельность политической партии, препятствующей устранению причин режима. Возможно ли это?','["Нет, политические партии полностью исключены из таких мер","Да, но без связи с поведением партии и причинами ЧП","Нет, это допускается только на основе муниципального опроса","Да, статья 12 допускает приостановление деятельности препятствующих устранению причин объединений"]'::jsonb,3,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 12','https://www.consultant.ru/document/cons_doc_LAW_31866/75a9b175e0a4d0c3074be68f272c7ac670e7eafc/','Статья 12 предусматривает такую меру именно в отношении препятствующих объединений.',true),
('Чрезвычайное положение: правовой режим','Чрезвычайное положение введено из-за масштабной природной катастрофы. Может ли указ предусмотреть карантинные и санитарно-противоэпидемические меры?','["Нет, карантин допускается лишь при вооружённом мятеже","Да, но только на основании нового федерального референдума","Да, при обстоятельствах пункта «б» статьи 3 они предусмотрены статьёй 13","Нет, любые санитарные меры являются компетенцией только частных организаций"]'::jsonb,2,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 13','https://www.consultant.ru/document/cons_doc_LAW_31866/2a4b8d119b407129ce84a1d1980c2b96ee2b8acd/','Статья 13 содержит соответствующие меры для обстоятельств пункта «б».',true),
('Чрезвычайное положение: правовой режим','Власти временно отселяют жителей из опасной зоны при ЧП из-за стихийного бедствия. Что им обязаны предоставить?','["Лишь денежный сертификат без предоставления помещений","Стационарные или временные жилые помещения","Только компенсацию транспортных расходов","Жилые помещения предоставляются только по решению суда"]'::jsonb,1,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 13','https://www.consultant.ru/document/cons_doc_LAW_31866/2a4b8d119b407129ce84a1d1980c2b96ee2b8acd/','Статья 13 предусматривает обязательное предоставление жилых помещений.',true),
('Чрезвычайное положение: правовой режим','При ЧП из-за аварии требуется привлечь трудоспособное население к срочным спасательным работам. Какое условие обязательно?','["Исключительный характер необходимости и соблюдение требований охраны труда","Любое усмотрение работодателя независимо от срочности","Отсутствие обязательств обеспечивать безопасность труда","Обязательное предварительное решение на федеральном референдуме"]'::jsonb,0,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 13','https://www.consultant.ru/document/cons_doc_LAW_31866/2a4b8d119b407129ce84a1d1980c2b96ee2b8acd/','Статья 13 допускает мобилизацию в исключительных случаях с соблюдением охраны труда.',true),
('Чрезвычайное положение: правовой режим','Срок полномочий выборного муниципального органа истёк на территории действующего ЧП. Что предусматривает закон, если полномочия не приостановлены?','["Немедленное проведение новых выборов","Автоматическую передачу полномочий региональной избирательной комиссии","Прекращение муниципального управления до назначения выборов","Продление полномочий до прекращения ЧП"]'::jsonb,3,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_31866/5e0f29e50ed491c2a56fd18209eec4103f386367/','Статья 14 предусматривает продление полномочий при указанном условии.',true),
('Чрезвычайное положение: правовой режим','Региональная комиссия предлагает провести местный референдум во время действующего на территории ЧП. Какое правило статьи 14 применимо?','["Допускается по решению губернатора при любой явке","Допускается после согласия половины местных депутатов","Выборы и референдумы на этой территории не проводятся в период ЧП","Допускается, если бюллетени напечатаны до введения режима"]'::jsonb,2,'ФКЗ от 30.05.2001 № 3-ФКЗ «О чрезвычайном положении»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_31866/5e0f29e50ed491c2a56fd18209eec4103f386367/','Статья 14 исключает проведение референдумов и выборов в период ЧП.',true),
('Военное положение: полномочия и меры','Правительство предлагает объявить военное положение из-за угрозы экономического спада без агрессии или непосредственной угрозы агрессии. Достаточно ли такого основания?','["Да, любой экономический спад достаточен","Нет, основание — агрессия против РФ либо её непосредственная угроза","Да, при одобрении финансового органа субъекта","Да, если падение ВВП превышает установленный региональным законом уровень"]'::jsonb,1,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 3','https://www.consultant.ru/document/cons_doc_LAW_35227/327d015f7dfa0a5f8fc16e7287d74337352aa1a2/','Статья 3 связывает введение военного положения с агрессией либо непосредственной угрозой.',true),
('Военное положение: полномочия и меры','Вооружённые силы иностранного государства установили блокаду российских портов. Может ли это относиться к актам агрессии по ФКЗ?','["Да, блокада портов или берегов прямо названа среди актов агрессии","Нет, агрессия возможна только при наземном вторжении","Да, лишь если блокада продолжается более 90 суток","Нет, вопрос относится исключительно к чрезвычайному положению"]'::jsonb,0,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 3','https://www.consultant.ru/document/cons_doc_LAW_35227/327d015f7dfa0a5f8fc16e7287d74337352aa1a2/','Статья 3 относит блокаду портов или берегов вооружёнными силами иностранного государства к актам агрессии.',true),
('Военное положение: полномочия и меры','Для введения военного положения подготовлено постановление Правительства без указа Президента. Что необходимо заменить?','["Достаточно федерального бюджета на мероприятия","Необходимо постановление Совета Федерации вместо президентского указа","Можно использовать любое распоряжение губернатора","Военное положение вводится указом Президента Российской Федерации"]'::jsonb,3,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_35227/1dee6e9a9da8e5358d817296d9fade6a123aa326/','Статья 4 требует президентского указа.',true),
('Военное положение: полномочия и меры','Какой срок установлен Совету Федерации для рассмотрения указа Президента о военном положении после получения, если нет чрезвычайных препятствий заседанию?','["72 часа с момента публикации","30 суток со дня введения режима","48 часов","14 календарных дней после опубликования"]'::jsonb,2,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_35227/1dee6e9a9da8e5358d817296d9fade6a123aa326/','Статья 4 устанавливает 48 часов со дня получения указа с указанной оговоркой.',true),
('Военное положение: полномочия и меры','Совет Федерации голосует по утверждению указа о военном положении. Какой порог необходим?','["Две трети присутствующих сенаторов","Большинство от общего числа сенаторов Российской Федерации","Не менее трёх четвертей от общего числа сенаторов","Большинство только от числа членов профильного комитета"]'::jsonb,1,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_35227/1dee6e9a9da8e5358d817296d9fade6a123aa326/','Статья 4 требует большинства от общего числа сенаторов.',true),
('Военное положение: полномочия и меры','Совет Федерации принял постановление о неутверждении указа Президента о военном положении. Когда указ прекращает действие?','["Со следующего дня после дня принятия такого постановления","Немедленно через 48 часов после официального опубликования","Через 72 часа после начала обсуждения","По истечении 30 суток без отдельного решения"]'::jsonb,0,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_35227/1dee6e9a9da8e5358d817296d9fade6a123aa326/','Статья 4 прямо устанавливает прекращение действия со следующего дня после постановления.',true),
('Военное положение: полномочия и меры','В указе о введении военного положения не указаны границы территории режима. Как оценить его содержание?','["Границы можно не указывать при введении в одном субъекте","Границы определяет исключительно Совет Федерации позднее","Достаточно указать только дату начала","Не соблюдено обязательное требование к содержанию президентского указа"]'::jsonb,3,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_35227/1dee6e9a9da8e5358d817296d9fade6a123aa326/','Статья 4 требует определения границ территории.',true),
('Военное положение: полномочия и меры','Военное положение введено в регионе; для нужд обороны необходимо изъять имущество организации. Какая обязанность государства предусмотрена?','["Изъятие без компенсации при любом виде имущества","Только обещание компенсировать по итогам будущего референдума","Выплата стоимости изъятого имущества в порядке федерального закона","Компенсацию может отменить местная администрация"]'::jsonb,2,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_35227/7d26c4e1754d86f891581f27b402a422efd344e0/','Статья 7 предусматривает возмещение стоимости необходимого для обороны изъятого имущества.',true),
('Военное положение: полномочия и меры','Предлагается переселить людей с территории военного положения без предоставления жилья. Соответствует ли это предусмотренной мере?','["Да, жильё обязательно лишь после прекращения режима","Нет, временное отселение связано с обязательным предоставлением жилья","Да, если решение поддержал региональный парламент","Да, поскольку режим исключает социальные гарантии"]'::jsonb,1,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_35227/7d26c4e1754d86f891581f27b402a422efd344e0/','Статья 7 предусматривает предоставление стационарных или временных жилых помещений.',true),
('Военное положение: полномочия и меры','В условиях военного положения избирательная комиссия хочет провести местные выборы. Какое из решений соответствует специальному исключению из общего запрета?','["Решение ЦИК России после консультаций с федеральными органами обороны и безопасности","Решение губернатора без консультаций с федеральными органами","Решение муниципального представительного органа при любой явке","Решение Правительства РФ без участия ЦИК"]'::jsonb,0,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_35227/7d26c4e1754d86f891581f27b402a422efd344e0/','Статья 7 допускает исключение по решению ЦИК после соответствующих консультаций.',true),
('Военное положение: полномочия и меры','Вводится военное положение. Может ли вводиться военная цензура почтовых отправлений и телекоммуникационных сообщений по предусмотренным законом мерам?','["Нет, такая мера запрещена при любом режиме","Да, исключительно по решению местного референдума","Нет, мера применяется только к гражданским судебным решениям","Да, статья 7 допускает военную цензуру и создание её органов"]'::jsonb,3,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_35227/7d26c4e1754d86f891581f27b402a422efd344e0/','Статья 7 включает военную цензуру среди возможных мер.',true),
('Военное положение: полномочия и меры','Какой максимальный срок административного задержания по специальному основанию нарушения запретов и ограничений военного положения предусмотрен статьёй 7?','["До 72 часов независимо от закона","До 60 суток по усмотрению администрации","До 30 суток в порядке федерального закона","До 14 суток по решению представительного органа"]'::jsonb,2,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 7','https://www.consultant.ru/document/cons_doc_LAW_35227/7d26c4e1754d86f891581f27b402a422efd344e0/','Подпункт 12.1 статьи 7 предусматривает срок до 30 суток.',true),
('Военное положение: полномочия и меры','Регулирование финансовой деятельности из-за военного положения предполагается только в регионе его введения. Может ли ФКЗ предусматривать связанные меры на иных территориях РФ?','["Нет, любые меры ограничены исключительно территорией режима","Да, меры статьи 8 могут применяться и там, где военное положение не введено","Да, но только после решения регионального парламента","Нет, закон допускает лишь меры по передвижению граждан"]'::jsonb,1,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_35227/37b24f42c64380e9d53199ffdcff2900e9941cbd/','Статья 8 предусматривает возможность экономических и финансовых мер за пределами территории военного положения.',true),
('Военное положение: полномочия и меры','Законодатель хочет подготовить правила экономических ограничений для военного положения заранее, до его введения. Допускает ли это ФКЗ?','["Да, соответствующие федеральные акты могут приниматься и до введения режима","Нет, правовые акты могут появиться только после указа Президента","Да, но лишь в течение 48 часов после голосования Совета Федерации","Нет, подготовка заранее разрешена только для актов о чрезвычайном положении"]'::jsonb,0,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_35227/37b24f42c64380e9d53199ffdcff2900e9941cbd/','Статья 8 допускает принятие соответствующих актов до или во время действия режима.',true),
('Военное положение: полномочия и меры','В парламенте обсуждается закон о мерах обеспечения военного положения. Какая палата принимает, а какая рассматривает такой федеральный закон?','["Совет Федерации принимает, Государственная Дума рассматривает","Каждая палата самостоятельно принимает отдельный федеральный закон","Закон принимается только на совместном заседании двух палат","Государственная Дума принимает, Совет Федерации рассматривает"]'::jsonb,3,'ФКЗ от 30.01.2002 № 1-ФКЗ «О военном положении»','статья 12','https://www.consultant.ru/document/cons_doc_LAW_35227/3095586a88e45d4226ecd183ff5edb380f472645/','Статья 12 распределяет полномочия по законодательному процессу между палатами.',true)
